import java.util.*;
import java.io.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        PrintWriter pw = new PrintWriter(System.out);
        String[] parts = br.readLine().split(" ");
        int n = Integer.parseInt(parts[0]);
        int m = Integer.parseInt(parts[1]);
        long total = 0;

        if (n > 100) {
            int remN = (n - 100) % 6;
            long qN = (n - 100) / 6;
            total += qN * 6 * m;
            n = 100 + remN;
        }

        if (m > 100) {
            int remM = (m - 100) % 6;
            long qM = (m - 100) / 6;
            total += qM * 6 * n;
            m = 100 + remM;
        }

        int[][] grid = new int[n + 1][m + 1];
        int uLabel = 1;
        int vLabel = 1;

        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= m; j++) {
                if ((i + j) % 2 == 0) {
                    grid[i][j] = uLabel++;
                }
            }
        }

        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= m; j++) {
                if ((i + j) % 2 != 0) {
                    grid[i][j] = vLabel++;
                }
            }
        }

        List<Integer>[] adj = new ArrayList[uLabel];
        for (int i = 0; i < uLabel; i++) {
            adj[i] = new ArrayList<>();
        }

        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= m; j++) {
                if ((i + j) % 2 == 0) {
                    addEdge(grid, adj, i, j, i - 3, j);
                    addEdge(grid, adj, i, j, i - 2, j - 1);
                    addEdge(grid, adj, i, j, i - 2, j + 1);
                    addEdge(grid, adj, i, j, i, j - 3);
                    addEdge(grid, adj, i, j, i - 1, j - 2);
                    addEdge(grid, adj, i, j, i + 1, j - 2);
                    addEdge(grid, adj, i, j, i, j + 3);
                    addEdge(grid, adj, i, j, i - 1, j + 2);
                    addEdge(grid, adj, i, j, i + 1, j + 2);
                    addEdge(grid, adj, i, j, i + 3, j);
                    addEdge(grid, adj, i, j, i + 2, j - 1);
                    addEdge(grid, adj, i, j, i + 2, j + 1);
                }
            }
        }

        int maxMatch = hopcroftKarp(adj, uLabel - 1, vLabel - 1);
        total += 2L * maxMatch;
        pw.println(total);
        pw.close();
    }

    static void addEdge(int[][] grid, List<Integer>[] g, int i, int j, int s, int t) {
        int n = grid.length - 1;
        int m = grid[0].length - 1;
        if (s <= 0 || t <= 0 || s > n || t > m) return;
        g[grid[i][j]].add(grid[s][t]);
    }

    static int hopcroftKarp(List<Integer>[] g, int m, int n) {
        int[] pairU = new int[m + 1];
        int[] pairV = new int[n + 1];
        int[] dist = new int[m + 1];
        Arrays.fill(pairU, 0);
        Arrays.fill(pairV, 0);
        int result = 0;

        while (bfs(g, pairU, pairV, dist, m)) {
            for (int u = 1; u <= m; u++) {
                if (pairU[u] == 0 && dfs(g, u, pairU, pairV, dist)) {
                    result++;
                }
            }
        }
        return result;
    }

    static boolean bfs(List<Integer>[] g, int[] pairU, int[] pairV, int[] dist, int m) {
        Queue<Integer> queue = new LinkedList<>();
        for (int u = 1; u <= m; u++) {
            if (pairU[u] == 0) {
                dist[u] = 0;
                queue.offer(u);
            } else {
                dist[u] = Integer.MAX_VALUE;
            }
        }
        int maxDist = Integer.MAX_VALUE;
        while (!queue.isEmpty()) {
            int u = queue.poll();
            if (dist[u] < maxDist) {
                for (int v : g[u]) {
                    if (pairV[v] == 0) {
                        maxDist = dist[u] + 1;
                    } else if (dist[pairV[v]] == Integer.MAX_VALUE) {
                        dist[pairV[v]] = dist[u] + 1;
                        queue.offer(pairV[v]);
                    }
                }
            }
        }
        return maxDist != Integer.MAX_VALUE;
    }

    static boolean dfs(List<Integer>[] g, int u, int[] pairU, int[] pairV, int[] dist) {
        if (u != 0) {
            for (int v : g[u]) {
                if (pairV[v] == 0 || (dist[pairV[v]] == dist[u] + 1 && dfs(g, pairV[v], pairU, pairV, dist))) {
                    pairU[u] = v;
                    pairV[v] = u;
                    return true;
                }
            }
            dist[u] = Integer.MAX_VALUE;
            return false;
        }
        return true;
    }
}
